using System;using System.Collections.Generic;using System.Reflection;using NUnit.Framework;using Rootborn.Game.Common;using Rootborn.Game.Localization;using Rootborn.Game.StudentLife;using Rootborn.UI.StudentLife;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Object=UnityEngine.Object;
namespace Rootborn.Tests.EditMode.UI.StudentLife{public sealed class DailyEventPresentationTests{GameObject canvas;DailyEventPanel panel;string language;readonly List<Object> owned=new List<Object>();[SetUp]public void Setup(){language=GameText.Language;GameText.Language="ko";GameDataRegistryProvider.SetOverrideForTests(AssetDatabase.LoadAssetAtPath<GameDataRegistry>("Assets/Data/Registry/GameDataRegistry.asset"));canvas=new GameObject("EventCanvas",typeof(RectTransform),typeof(Canvas));panel=DailyEventPanel.EnsureInScene(canvas.GetComponent<Canvas>());}[TearDown]public void Cleanup(){Object.DestroyImmediate(canvas);foreach(var o in owned)if(o!=null)Object.DestroyImmediate(o);owned.Clear();GameText.Language=language;GameDataRegistryProvider.ClearOverrideForTests();}
[Test]public void EventIsPaddedReadableModalWithDimensionalButtonsAndSharedFont(){panel.Show(null,null);var root=panel.transform.Find("DailyEventRoot").GetComponent<RectTransform>();Assert.That(root.rect.size,Is.EqualTo(new Vector2(1120,800)));var modal=root.GetComponent<Canvas>();Assert.That(modal,Is.Not.Null);Assert.That(modal.overrideSorting,Is.True);Assert.That(modal.sortingOrder,Is.GreaterThan(1200));Assert.That(root.GetComponent<GraphicRaycaster>(),Is.Not.Null);foreach(var b in root.GetComponentsInChildren<Button>(true)){Assert.That(b.GetComponent<Rootborn.UI.Modern.ModernUiTileImage>(),Is.Not.Null,b.name);var r=(RectTransform)b.transform;Assert.That(root.rect.xMax-(r.anchoredPosition.x+r.rect.width*.5f),Is.GreaterThanOrEqualTo(32),b.name);Assert.That((r.anchoredPosition.y-r.rect.height*.5f)-root.rect.yMin,Is.GreaterThanOrEqualTo(32),b.name);}var shared=(Font)typeof(LocationIdentityPanel).Assembly.GetType("Rootborn.UI.StudentLife.LifeUiFont").GetProperty("Shared").GetValue(null);foreach(var t in root.GetComponentsInChildren<Text>(true))Assert.That(t.font,Is.SameAs(shared));}
[TestCase(false)][TestCase(true)]public void CloseOrDisableReleasesOnlyItsOwnWorldLock(bool disable){panel.Show(null,null);Assert.That(UiGameplayInputLock.IsBlocked,Is.True);var other=new GameObject("AnotherModal");owned.Add(other);UiGameplayInputLock.Acquire(other);if(disable)panel.gameObject.SetActive(false);else panel.transform.Find("DailyEventRoot/DailyEventCloseButton").GetComponent<Button>().onClick.Invoke();Assert.That(UiGameplayInputLock.IsBlocked,Is.True);UiGameplayInputLock.Release(other);Assert.That(UiGameplayInputLock.IsBlocked,Is.False);Assert.That(panel.IsOpen,Is.False);}
[TestCase("ko")][TestCase("en")]public void AuthoredEventAndChoicesResolveBilingualKeysWithoutRawIds(string lang){GameText.Language=lang;var authored=AssetDatabase.LoadAssetAtPath<DailyEventDefinition>("Assets/Data/StudentLife/DailyEvents/DailyEvent_LibraryHardBook.asset");panel.Show(authored,null);Assert.That(panel.transform.Find("DailyEventRoot/DailyEventTitle").GetComponent<Text>().text,Is.EqualTo(GameText.Get("life.event.library.name")));Assert.That(panel.transform.Find("DailyEventRoot/DailyEventDescription").GetComponent<Text>().text,Is.EqualTo(GameText.Get("life.event.library.description")));Assert.That(panel.transform.Find("DailyEventRoot/DailyEventChoiceButton_0/Label").GetComponent<Text>().text,Does.Contain(GameText.Get("life.event.choice.read.name")));foreach(var t in panel.GetComponentsInChildren<Text>()){Assert.That(t.text,Does.Not.Contain("life.event.").And.Not.Contain("daily-event:"));if(!string.IsNullOrWhiteSpace(t.text))Assert.That(t.preferredHeight,Is.LessThanOrEqualTo(t.rectTransform.rect.height+3),t.name);}}
}}
